function db():PDO{return settings_db();}function json_response(array $p,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');echo json_encode($p,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}function body():array{$d=json_decode(file_get_contents('php://input')?:'{}',true);return is_array($d)?$d:[];}function bearer_token():string{$h=$_SERVER['HTTP_AUTHORIZATION']??'';return stripos($h,'Bearer ')===0?trim(substr($h,7)):'';}function public_base_url():string{return runtime_public_url();}function activation_code():string{return(string)random_int(100000,999999);}function device_token():string{return rtrim(strtr(base64_encode(random_bytes(36)),'+/','-_'),'=');}function venue_code(string $n):string{$b=strtoupper(preg_replace('/[^A-Za-z0-9]+/','',iconv('UTF-8','ASCII//TRANSLIT',$n)?:$n));return substr($b?:'BAR',0,8).random_int(100,999);}function unique_venue_code(string $n):string{do{$c=venue_code($n);$q=db()->prepare('SELECT id FROM venues WHERE code=?');$q->execute([$c]);}while($q->fetch());return$c;}
