function ensure_default_table(int $venueId):array{$q=db()->prepare("SELECT * FROM venueTables WHERE venueId=? AND label='Mesa 01' LIMIT 1");$q->execute([$venueId]);if($t=$q->fetch())return$t;$token=substr(strtolower(bin2hex(random_bytes(8))),0,14);$i=db()->prepare("INSERT INTO venueTables(venueId,label,qrToken) VALUES(?,'Mesa 01',?)");$i->execute([$venueId,$token]);$q->execute([$venueId]);return$q->fetch();}
