if($method==='POST'&&$path==='/api/onboarding/activate-tv'){$p=body();$code=preg_replace('/\D+/','',(string)($p['activationCode']??''));$owner=trim((string)($p['ownerName']??''));$bar=trim((string)($p['barName']??''));$phone=preg_replace('/\D+/','',(string)($p['phone']??''));$email=trim((string)($p['email']??''));$doc=preg_replace('/\D+/','',(string)($p['document']??''));$accepted=(bool)($p['acceptedTerms']??false);$tv=trim((string)($p['tvName']??'TV Principal'));if($code===''||$owner===''||$bar===''||$phone===''||$doc==='')json_response(['message'=>'Preencha cadastro, documento e telefone'],400);if(!$accepted)json_response(['message'=>'Aceite os termos'],400);ensure_onboarding_columns();$pdo=db();$q=$pdo->prepare('SELECT * FROM devices WHERE activationCode=? LIMIT 1');$q->execute([$code]);$device=$q->fetch();if(!$device||$device['status']!=='PENDING_ACTIVATION')json_response(['message'=>'Codigo da TV nao encontrado'],404);if(strtotime($device['activationCodeExpiresAt'])<time())json_response(['message'=>'Codigo da TV expirado. Reinicie o app na TV.'],410);$pdo->beginTransaction();try{$open='phone-'.hash('sha256',$phone);$q=$pdo->prepare('SELECT * FROM users WHERE openId=? LIMIT 1');$q->execute([$open]);$user=$q->fetch();if(!$user){$q=$pdo->prepare("INSERT INTO users(openId,name,email,loginMethod,role) VALUES(?,?,?,'phone','admin')");$q->execute([$open,$owner,$email?:null]);$uid=(int)$pdo->lastInsertId();}else{$uid=(int)$user['id'];$pdo->prepare('UPDATE users SET name=?,email=?,lastSignedIn=NOW() WHERE id=?')->execute([$owner,$email?:($user['email']??null),$uid]);}$venueCode=unique_venue_code($bar);$q=$pdo->prepare('INSERT INTO venues(ownerId,code,name,musicPriceCents,dedicationPriceCents,splitBarPercent,splitPlatformPercent,ownerDocument,ownerPhone,splitAcceptedAt,termsAcceptedAt) VALUES(?,?,?,300,200,70,30,?,?,NOW(),NOW())');$q->execute([$uid,$venueCode,$bar,$doc,$phone]);$venueId=(int)$pdo->lastInsertId();$pdo->prepare("UPDATE devices SET venueId=?,name=?,status='