if($method==='GET'&&$path==='/mesas'){$venue=preg_replace('/[^A-Za-z0-9]+/','',(string)($_GET['venue']??''));$q=db()->prepare('SELECT id,name,code,mercadoPagoAccessToken FROM venues WHERE code=? LIMIT 1');$q->execute([$venue]);$v=$q->fetch();if(!$v){http_response_code(404);exit('Bar nao encontrado');}$tq=db()->prepare("SELECT * FROM venueTables WHERE venueId=? AND status='ACTIVE' ORDER BY id");$tq->execute([(int)$v['id']]);$tables=$tq->fetchAll();if(!$tables)$tables=[ensure_default_table((int)$v['id'])];header('Content-Type:text/html;charset=utf-8');$name=htmlspecialchars((string)$v['name'],ENT_QUOTES,'UTF-8');$connected=!empty($v['mercadoPagoAccessToken']);echo '<!doctype html><html><head><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1"><title>QR Codes · TocaRaul</title><style>body{font-family:system-ui;background:#eee;padding:24px}.top{display:flex;gap:10px;flex-wrap:wrap}.btn{background:#111;color:#fff;padding:12px 16px;border:0;border-radius:10px;text-decoration:none}.mp{background:#ffcc00;color:#111}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px;margin-top:20px}.card{background:#fff;border:2px dashed #111;border-radius:20px;padding:22px;text-align:center}.qr{width:220px;height:220px;margin:auto}@media print{.top{display:none}body{background:#fff}.card{break-inside:avoid}}</style></head><body><h1>TocaRaul · '. $name .'</h1><div class=top><button class=btn onclick="window.print()">Imprimir / salvar PDF</button>'.(!$connected?'<a class="btn mp" href="/mp/oauth/start?venue='.rawurlencode($venue).'">Conectar Mercado Pago</a>':'<span class="btn">Mercado Pago conectado ✓</span>').'</div><div class=grid>';foreach($tables as$t){$url=public_base_url().'/j/'.$t['qrToken'];echo '<div class=card><h2>'.htmlspecialchars((string)$t['label']).'</h2><div class=qr data-url="'.htmlspecialchars($url,ENT_QUOTES).'" id="qr'.(int)$t['id'].'"></div><p>Escaneie para pedir música</p><small>'.htmlspecialchars($url).